pub fn complex_part_index(name: &str) -> Option<u16> {
    COMPLEX_PART_INDEX
        .binary_search_by(|(n, _)| (*n).cmp(name))
        .ok()
        .map(|i| COMPLEX_PART_INDEX[i].1)
}

